public class NestedDemo {
    static class Point {                       // static nested class
        int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    enum Level {
        LOW(1), MEDIUM(5), HIGH(10);            // enum with a field via constructor
        final int weight;
        Level(int weight) { this.weight = weight; }
    }

    public static void main(String[] args) {
        Point p = new Point(1, 2);
        System.out.println(p.x + "," + p.y);

        Runnable r = new Runnable() {           // anonymous class
            public void run() { System.out.println("Running anonymously"); }
        };
        r.run();

        System.out.println(Level.HIGH.weight);   // 10
    }
}
